  if (Number.isInteger(it.x) && it.x >= 1 && it.x <= 3) { const n = Number.isInteger(it.n) ? Math.max(1, Math.min(CHEST[it.x].n, it.n)) : CHEST[it.x].n; return n < CHEST[it.x].n ? { x: it.x, n } : { x: it.x }; }
  if (RES[it.r] && Number.isInteger(it.l) && it.l >= 1 && it.l <= RES_MAX) return { r: it.r, l: it.l };
  if (it.tool === 'cut' || it.tool === 'up') { const n = Math.max(1, Math.min(99, Math.floor(+it.n || 1))); return n > 1 ? { tool: it.tool, n } : { tool: it.tool }; }
