  if (o.cafeDone) s.areaDone.cafe = true;
  if (o.settings && CHAT_E_OPTIONS.includes(o.settings.chatE)) s.settings.chatE = o.settings.chatE;
  if (o.settings && [0, 1, 2, 3].includes(o.settings.sfx)) s.settings.sfx = o.settings.sfx;
