function setTab(ev) {
  if (!!ev === !!S.onEv || !S.ev) return;
  cancelDrag(); sel = -1;
  swapEv(); S.evTab = S.onEv;
  if (!S.onEv) placePending();
  renderAll(); save();
}
function checkEvent() {
  if (evOn()) {
    if (!S.ev) { S.ev = newEv(); return 'start'; }
    return null;
  }
  if (S.ev) {
    if (S.onEv) swapEv();
    let gain = 0;
    S.ev.board.forEach(it => { if (it && it.c) gain += sellPrice(it.l); else if (it && it.g) gain += 20; });
    S.coins += gain; S.ev = null; S.evTab = false;
    if (areaFull(AREAS.find(a => a.k === 'plaza'))) S.coll.xmas = true;
    return { end: true, gain };
  }
  return null;
}
function normState() {
  if (!S.onEv) return S;
  const e = S.ev;
  return Object.assign({}, S, { board: e.board, orders: e.orders, rows: e.rows, chains: e.chains, onEv: false, evTab: true,
    ev: Object.assign({}, e, { board: S.board, orders: S.orders, rows: S.rows, chains: S.chains }) });
}
async function loadState() {
  let a = null, b = null;
  try { const raw = await Risuai.pluginStorage.getItem(SAVE_KEY); if (raw) a = sanitize(JSON.parse(raw)); } catch (err) { console.log(TAG, 'pluginStorage load fail', err?.message); }
  try { localStore = await Risuai.getLocalPluginStorage(); const v = await localStore.getItem(SAVE_KEY); if (v) b = sanitize(typeof v === 'string' ? JSON.parse(v) : v); } catch (err) { console.log(TAG, 'local load fail', err?.message); }
  if (a && b) return a.savedAt >= b.savedAt ? a : b;
  return a || b || newState();
}

let saveTimer = null;
let lastRaw = '';
function save() { if (!saveTimer) saveTimer = setTimeout(flush, 8000); }
async function flush() {
  clearTimeout(saveTimer); saveTimer = null;
  if (!S) return;
  const st = normState(), cmp = JSON.stringify(Object.assign({}, st, { savedAt: 0 }));
  if (cmp === lastRaw) return;
  lastRaw = cmp;
  S.savedAt = Date.now();
  const raw = JSON.stringify(Object.assign(st, { savedAt: S.savedAt }));
  try { await Risuai.pluginStorage.setItem(SAVE_KEY, raw); } catch (err) { console.log(TAG, 'save fail', err?.message); }
  try { if (localStore) await localStore.setItem(SAVE_KEY, JSON.parse(raw)); } catch (err) { /* ignore */ }
}

// ---------- energy ----------
function tickEnergy() {
  const now = Date.now();
  const M = maxE(), RG = regenMs();
  if (!(S.eTs <= now)) S.eTs = now;
  if (S.energy >= M) { S.eTs = now; return; }
  const n = Math.floor((now - S.eTs) / RG);
  if (n > 0) {
    S.energy = Math.min(M, S.energy + n);
    S.eTs += n * RG;
    if (S.energy >= M) S.eTs = now;
    save();
  }
}
function spendEnergy(n) {
  tickEnergy();
  if (S.energy < n) return false;
  const wasFull = S.energy >= maxE();
  S.energy -= n;
  if (wasFull && S.energy < maxE()) S.eTs = Date.now();
  return true;
}
function addEnergy(n, overflow) {
  tickEnergy();
  const before = S.energy;
  S.energy = overflow ? S.energy + n : Math.max(S.energy, Math.min(maxE(), S.energy + n));
  return S.energy - before;
}

// ---------- orders ----------
function genOrder(st) {
  const lv = st.level, chains = st.chains;
  const maxL = Math.min(hiOpen() ? 10 : 7, 2 + Math.ceil(lv / 2));
  const minL = lv >= 7 ? 3 : 2;
  const n = lv >= 4 ? 3 : Math.random() < 0.5 ? 2 : 1;
  const req = [], used = new Set();
  // Lv.8 이상(4장부터)은 주문 하나에 최대 1개, 18% 확률로만
  const capL = Math.min(maxL, ORD_HI - 1);
  for (let i = 0; i < n; i++) {
    const c = pick(chains.filter(x => !used.has(x)).length ? chains.filter(x => !used.has(x)) : chains);
    used.add(c);
    const opts = [];
    for (let l = minL; l <= capL; l++) for (let w = 0; w < maxL - l + 1; w++) opts.push(l);
    req.push({ c, l: Math.min(maxLvOf(c), pick(opts)) });
  }
  if (maxL >= ORD_HI && Math.random() < ORD_HI_P) {
    const r = pick(req), ho = [];
    for (let l = ORD_HI; l <= maxL; l++) for (let w = 0; w < maxL - l + 1; w++) ho.push(l);
    r.l = Math.min(maxLvOf(r.c), pick(ho));
  }
  const taken = new Set(st.orders.map(o => o.a));
  const ad = st.areaDone || (S && S.areaDone) || {};
  const avail = ANIMALS.map((_, i) => i).filter(i => !ANIMALS[i].ch2 || ad[ANIMALS[i].ch2]);
  const free = avail.filter(i => !taken.has(i));
  return {
    id: st.nextId++, a: pick(free.length ? free : avail), req,
    coins: req.reduce((s, r) => s + orderCoins(r.l), 0),
    xp: req.reduce((s, r) => s + orderXp(r.l), 0),
    en: Math.random() < 0.2 + 0.1 * ((st.decor && st.decor.door) || 0) ? 5 : 0,
  };
}
function boardCounts() {
  const m = {};
  S.board.forEach(it => { if (it && it.c) { const k = it.c + ':' + it.l; m[k] = (m[k] || 0) + 1; } });
  return m;
}
function orderReady(od, counts) {
  const need = {};
  od.req.forEach(r => { const k = r.c + ':' + r.l; need[k] = (need[k] || 0) + 1; });
  return Object.keys(need).every(k => (counts[k] || 0) >= need[k]);
}
function completeOrder(id) {
  const oi = S.orders.findIndex(o => o.id === id);
  if (oi < 0) return;
  const od = S.orders[oi];
  if (!orderReady(od, boardCounts())) return;
  for (const r of od.req) {
    const i = S.board.findIndex(it => it && it.c === r.c && it.l === r.l);
    S.board[i] = null;
    if (sel === i) sel = -1;
  }
  const cardEl = $(`.mc-ord[data-id="${id}"]`);
  const from = cardEl ? cardEl.getBoundingClientRect() : null;
  S.coins += coinsOf(od);
  if (S.onEv) S.snow += starsOf(od); else S.stars += starsOf(od);
  sfx('order');
  if (od.en) addEnergy(od.en, true);
  S.stats.orders++;
  S.orders[oi] = genOrder(S);
  fx.push({ t: 'order', id: S.orders[oi].id });
  if (from) { if (!S.onEv) flyCoins(from, Math.min(6, 2 + Math.floor(od.coins / 15)), '#mc-co', UI.coin); flyCoins(from, starsOf(od), S.onEv ? '#mc-co' : '#mc-cafeb', S.onEv ? SNOW : UI.star); }
  gainXp(xpOf(od));
  placePending();
  renderAll(); save();
}

