    box.innerHTML = `<div class="ii evo" data-act="evo" title="머지 단계 보기">${iconRes(it.r, it.l)}<span class="q">?</span></div><div class="tx"><b>${esc(R.items[it.l - 1])}</b><div class="mc-sub">${esc(RES_DESC[it.r][it.l - 1])}</div></div>
    <div class="mc-sellw"><span class="sl">받기</span><button class="mc-sellb" data-act="use" title="받기"><i>${ic}</i><b>+${v}</b></button></div>`;
