const verCmp = (a, b) => { const x = a.split('.').map(Number), y = b.split('.').map(Number); for (let i = 0; i < 3; i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) - (y[i] || 0); return 0; };
function openNotes(since) {
  const list = since ? NOTES.filter(([v]) => verCmp(v, since) > 0).slice(0, 4) : NOTES;
  if (!list.length) return;
  modal(`<h3>${since ? '업데이트 소식' : '업데이트 내역'}</h3><div class="mc-notes">${list.map(([v, items]) => `<div class="nt"><b>v${v}</b><ul>${items.map(t => `<li>${esc(t)}</li>`).join('')}</ul></div>`).join('')}</div>
    <div class="acts"><button class="mc-btn pk" data-x>확인</button></div>`);
}
function modal(html, onMount, sticky) {
  $('.mc-modal')?.remove();
  const m = document.createElement('div');
  m.className = 'mc-modal';
  m.innerHTML = `<div class="mc-card">${html}</div>`;
  m.addEventListener('click', ev => { if ((!sticky && ev.target === m) || ev.target.closest('[data-x]')) m.remove(); });
  $('.mc-panel').appendChild(m);
  onMount?.(m);
  return m;
}
function confirmBox(html, okLabel) {
  return new Promise(res => {
    const m = modal(`<p>${html}</p><div class="acts"><button class="mc-btn wh" data-no>취소</button><button class="mc-btn pk" data-yes>${esc(okLabel)}</button></div>`);
    m.querySelector('[data-no]').onclick = () => { m.remove(); res(false); };
    m.querySelector('[data-yes]').onclick = () => { m.remove(); res(true); };
    m.addEventListener('click', ev => { if (ev.target === m) res(false); });
  });
}
