        txt = await extSeq(async () => { await extBust('mail'); const r = await Promise.race([Risuai.nativeFetch(q, { method: 'GET' }), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 15000))]); if (!r || r.status < 200 || r.status >= 300) throw new Error('HTTP ' + (r && r.status)); return new TextDecoder().decode(new Uint8Array(await r.arrayBuffer())); });
