    if (!x || typeof x.id !== 'string' || !x.id || S.mail.got[x.id]) continue;
    if (x.until && String(x.until) < now) continue;
    if (x.since && String(x.since) > now) continue;
    if (x.minVer && verCmp(VER, String(x.minVer)) < 0) continue;
    if (x.maxVer && verCmp(VER, String(x.maxVer)) > 0) continue;
    S.mail.got[x.id] = 1;
